//! Correlation is generated by the transport, never copied from a business argument.
use super::{contract::*, diagnostic_types::Event, security::Security};
use serde_json::Value;
use std::cell::RefCell;
thread_local! {static REQUEST: RefCell<Option<String>> = const { RefCell::new(None) };}
pub fn current() -> Option<String> {
    REQUEST.with(|r| r.borrow().clone())
}
pub fn with_request<T>(id: String, f: impl FnOnce() -> T) -> T {
    struct Restore(Option<String>);
    impl Drop for Restore {
        fn drop(&mut self) {
            REQUEST.with(|r| *r.borrow_mut() = self.0.take());
        }
    }
    let _restore = Restore(REQUEST.with(|r| r.replace(Some(id))));
    f()
}
impl Security {
    pub fn observe(
        &self,
        credentials: &Credentials,
        tool: &str,
        request: String,
        result: &Result<Value, McpError>,
        elapsed: u64,
        refs: &Value,
    ) {
        // Token ownership is established even for paused/revoked calls. Unknown credentials
        // never claim a victim's last-call state or expose a diagnostic to another client.
        let client = self
            .store
            .lock()
            .ok()
            .and_then(|s| s.credential_owner(credentials))
            .or_else(|| {
                refs["_diagnosticOwner"]
                    .as_str()
                    .filter(|s| s.len() == 64 && s.bytes().all(|b| b.is_ascii_hexdigit()))
                    .map(String::from)
            });
        let code = match result {
            Err(e) => e.code.as_str(),
            Ok(v) if v["verificationStatus"] == "verification_failed" => "verification_failed",
            Ok(v)
                if v["meta"]["cache"]["stored"] == false
                    && v["meta"]["cache"]["validationStatus"]
                        == "current_basis_and_authorization" =>
            {
                if self.cache.lock().ok().is_some_and(|mut c| {
                    c.info(None)["capacityBypasses"]
                        .as_u64()
                        .is_some_and(|n| n >= 3)
                }) {
                    "cache_capacity"
                } else {
                    "cache_bypass"
                }
            }
            Ok(_) => "ok",
        };
        let db = self.diagnostic_db.lock().ok().and_then(|d| d.clone());
        let basis = db.as_ref().and_then(|d| d.mcp_basis().ok());
        let valid_authorization = self
            .store
            .lock()
            .ok()
            .is_some_and(|s| s.authorize(credentials).is_ok());
        let verified = code == "ok"
            && valid_authorization
            && self.verify_private_store().is_ok()
            && db
                .as_ref()
                .is_some_and(|d| d.mcp_quality_health().is_ok_and(|h| h["healthy"] == true))
            && result.as_ref().is_ok_and(|v| match tool {
                "get_capabilities" => true,
                "inspect_data" => {
                    v["health"]["healthy"] == true
                        && v["snapshot"].is_null()
                        && v["cursor"].is_null()
                }
                "cli_complete_task" | "cli_create_subtask" => {
                    v["verificationStatus"] == "verified_after_commit"
                        && matches!(v["commitStatus"].as_str(), Some("committed" | "no_change"))
                }
                "mutate_task" | "batch_mutate" | "manage_preferences" => {
                    v["verificationStatus"] == "verified_in_transaction"
                        && v["commitStatus"] == "committed"
                }
                _ => {
                    basis.as_ref().is_some_and(|b| {
                        v["meta"]["dataVersion"] == serde_json::to_value(b).unwrap_or(Value::Null)
                    }) && v["hasMore"] != true
                        && v["complete"] != false
                }
            });
        let event = Event {
            receipt_hash: refs["_diagnosticKeyHash"].as_str().map(String::from),
            request_id: request,
            client,
            tool: tool.into(),
            module: String::new(),
            code: code.into(),
            at: chrono::Utc::now().timestamp(),
            duration_ms: elapsed,
            job_id: refs["job"]["jobId"].as_str().map(String::from),
            round: refs["job"]["finalRound"]
                .as_u64()
                .and_then(|n| n.try_into().ok()),
            audit_id: refs["auditId"].as_i64(),
            data_version: basis,
            build: super::build_identity::current(),
        };
        let _ = self.diagnostics.record(event, verified); // Observer failure never changes a committed result.
    }
    pub fn bind_diagnostic_database(&self, db: crate::database::Database) {
        if let Ok(mut d) = self.diagnostic_db.lock() {
            *d = Some(db);
        }
    }
}
